  ["0a6af3220962e6ac"] = { "Mago", "." },
  ["0a7ea56df8b9f4ea"] = { "Ho perso il mio ⟦Gavel of Infinite Wisdom=Martellaccio della Saggezza Infinita⟧. Puoi sostituirmelo?", "." },
